import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import io from 'socket.io-client';
import './DMPage.css';

const DMPage = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const messagesEndRef = useRef(null);
  const navigate = useNavigate();
  const [socket, setSocket] = useState(null);

  const currentUser = JSON.parse(localStorage.getItem('user'));

  useEffect(() => {
    const token = localStorage.getItem('token');
    const newSocket = io('http://localhost:5001', {
      auth: { token },
      transports: ['websocket']
    });
    setSocket(newSocket);

    newSocket.on('receiveMessage', (message) => {
      if (selectedConversation?._id === message.conversationId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => newSocket.disconnect();
  }, [selectedConversation]);

  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const res = await fetch('http://localhost:5001/api/conversations', {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        const { data } = await res.json();
        setConversations(data);
      } catch (err) {
        console.error('Error:', err);
      } finally {
        setLoading(false);
      }
    };
    fetchConversations();
  }, []);

  useEffect(() => {
    if (!selectedConversation) return;
    const fetchMessages = async () => {
      try {
        const res = await fetch(
          `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
          { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
        );
        const { data } = await res.json();
        setMessages(data);
      } catch (err) {
        console.error('Error:', err);
      }
    };
    fetchMessages();
  }, [selectedConversation]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;
    try {
      const tempMessage = {
        _id: Date.now().toString(),
        sender: currentUser,
        text: newMessage,
        timestamp: new Date(),
        isOptimistic: true
      };
      setMessages(prev => [...prev, tempMessage]);

      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${localStorage.getItem('token')}`
          },
          body: JSON.stringify({ message: newMessage })
        }
      );

      const { data } = await res.json();
      setMessages(prev => prev.filter(m => !m.isOptimistic).concat(data));

      socket?.emit('sendMessage', {
        conversationId: selectedConversation._id,
        sender: currentUser?._id,
        receiver: selectedConversation?.participants?.find(p => p._id !== currentUser._id)?._id,
        message: newMessage
      });

      setNewMessage('');
    } catch (err) {
      console.error('Error:', err);
      setMessages(prev => prev.filter(m => !m.isOptimistic));
    }
  };

  if (!currentUser) {
    navigate('/login');
    return null;
  }

  if (loading) return <div className="loading">Loading conversations...</div>;

  return (
    <div className="dm-container">
      <div className="conversation-list">
        <h2>Conversations</h2>
        {conversations.map(conv => {
          const otherUser = conv.participants.find(p => p?._id !== currentUser._id);
          return (
            <div 
              key={conv._id}
              className={`conversation-item ${selectedConversation?._id === conv._id ? 'active' : ''}`}
              onClick={() => setSelectedConversation(conv)}
            >
              <img src={otherUser?.image || '/default-user.png'} alt={otherUser?.name} />
              <div className="conversation-info">
                <h3>{otherUser?.name || 'Unknown User'}</h3>
                <p>{conv.lastMessage?.message?.substring(0, 30) || 'No messages'}</p>
              </div>
            </div>
          );
        })}
      </div>
      <div className="chat-area">
        {selectedConversation ? (
          <>
            <div className="chat-header">
              <h3>{selectedConversation?.participants?.find(p => p._id !== currentUser._id)?.name}</h3>
            </div>
            <div className="messages-container">
              {messages.map(msg => (
                <div key={msg._id} className={`message ${msg.sender?._id === currentUser._id ? 'sent' : 'received'}`}>
                  <div className="message-content">
                    <p>{msg.text || msg.message}</p>
                    <span className="timestamp">{new Date(msg.timestamp).toLocaleTimeString()}</span>
                  </div>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>
            <div className="message-input">
              <input
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
              />
              <button onClick={handleSendMessage}>Send</button>
            </div>
          </>
        ) : (
          <div className="no-conversation">
            <p>Select a conversation to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DMPage;
